import axios from "axios";
import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addToCart } from "../Redux/Slice";

export default function Products() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  const dispatch = useDispatch();
  const navigate = useNavigate();

  const cartItems = useSelector(
    (state) => state.cart.items
  );

  // =========================
  // FETCH PRODUCTS
  // =========================

  const fetchProducts = async () => {
    try {
      setLoading(true);
      setError("");

      const token = localStorage.getItem("token");

      const response = await axios.get(
        "http://localhost:5000/api/v1/products",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setProducts(response.data.data || []);
    } catch (error) {
      console.error(
        error.response?.data || error.message
      );

      setError(
        error.response?.data?.message ||
          "Unable to load products."
      );
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // =========================
  // SEARCH
  // =========================

  const filteredProducts = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    if (!keyword) {
      return products;
    }

    return products.filter((item) =>
      item.name?.toLowerCase().includes(keyword)
    );
  }, [products, search]);

  // =========================
  // STOCK
  // =========================

  const getStock = (item) => {
    return Number(
      item.quantity ?? item.stock ?? 0
    );
  };

  const inStock = products.filter(
    (item) => getStock(item) > 10
  ).length;

  const lowStock = products.filter((item) => {
    const stock = getStock(item);

    return stock > 0 && stock <= 10;
  }).length;

  const outOfStock = products.filter(
    (item) => getStock(item) <= 0
  ).length;

  // =========================
  // PRODUCT CARD
  // =========================

  const ProductCard = ({ item }) => {
    const isInCart = cartItems.some(
      (cartItem) => cartItem.id === item.id
    );

    const stock = getStock(item);

    let stockClass = "out";
    let stockText = "Out of stock";

    if (stock > 10) {
      stockClass = "good";
      stockText = "In stock";
    } else if (stock > 0) {
      stockClass = "low";
      stockText = "Low stock";
    }

    return (
      <article className="product-card">

        {/* IMAGE */}

        <div className="product-image-area">

          <img
            src={
              item.image ||
              "https://via.placeholder.com/500x400?text=No+Image"
            }
            alt={item.name || "Product"}
            className="product-image"
          />

          <span className="product-number">
            #{item.id}
          </span>

          <span
            className={`stock-pill ${stockClass}`}
          >
            <span className="stock-dot"></span>
            {stockText}
          </span>

        </div>

        {/* CONTENT */}

        <div className="product-card-content">

          <div className="product-type">
            SHOPNEST PRODUCT
          </div>

          <h3 className="product-name">
            {item.name || "Unnamed Product"}
          </h3>

          <p className="product-description">
            {item.description ||
              "No description available for this product."}
          </p>

          {/* PRICE / STOCK */}

          <div className="product-bottom-info">

            <div className="price-block">
              <span>PRICE</span>

              <strong>
                ₹
                {Number(
                  item.price || 0
                ).toLocaleString("en-IN")}
              </strong>
            </div>

            <div className="available-block">
              <span>AVAILABLE</span>

              <strong>
                {stock > 0
                  ? `${stock} units`
                  : "None"}
              </strong>
            </div>

          </div>

          {/* CART */}

          <button
            className={`cart-button ${
              isInCart ? "added" : ""
            }`}
            disabled={isInCart || stock <= 0}
            onClick={() =>
              dispatch(addToCart(item))
            }
          >
            <span>
              {isInCart ? "✓" : "🛒"}
            </span>

            {isInCart
              ? "Added to cart"
              : stock <= 0
              ? "Out of stock"
              : "Add to cart"}
          </button>

        </div>
      </article>
    );
  };

  return (
    <>
      <style>{`

        /* =========================================
           PAGE
        ========================================= */

        .products-page {
          min-height: 100vh;
          padding: 28px;
          background: #f6f8fb;
          color: #172033;
          box-sizing: border-box;
        }


        /* =========================================
           HEADER
        ========================================= */

        .products-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          gap: 20px;
          margin-bottom: 25px;
        }

        .products-heading {
          min-width: 0;
        }

        .products-label {
          display: inline-flex;
          align-items: center;
          gap: 6px;
          color: #2563eb;
          font-size: 10px;
          font-weight: 800;
          letter-spacing: 1.5px;
          margin-bottom: 7px;
        }

        .products-heading h1 {
          margin: 0;
          font-size: 28px;
          line-height: 1.2;
          font-weight: 800;
          letter-spacing: -0.5px;
          color: #111827;
        }

        .products-heading p {
          margin: 7px 0 0;
          color: #6b7280;
          font-size: 13px;
        }

        .add-product-button {
          border: none;
          background: #111827;
          color: #ffffff;
          padding: 11px 17px;
          border-radius: 9px;
          font-size: 12px;
          font-weight: 700;
          cursor: pointer;
          white-space: nowrap;
          transition: all 0.25s ease;
        }

        .add-product-button:hover {
          background: #2563eb;
          transform: translateY(-2px);
          box-shadow:
            0 8px 18px
            rgba(37, 99, 235, 0.20);
        }


        /* =========================================
           STATS
        ========================================= */

        .products-stats {
          display: grid;
          grid-template-columns:
            repeat(4, minmax(0, 1fr));
          gap: 14px;
          margin-bottom: 20px;
        }

        .stat-card {
          position: relative;
          overflow: hidden;
          background: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 12px;
          padding: 15px;
          display: flex;
          align-items: center;
          gap: 12px;
          transition: all 0.25s ease;
        }

        .stat-card::after {
          content: "";
          position: absolute;
          right: -18px;
          bottom: -22px;
          width: 65px;
          height: 65px;
          border-radius: 50%;
          background: #eff6ff;
        }

        .stat-card:hover {
          transform: translateY(-2px);
          border-color: #dbeafe;
          box-shadow:
            0 8px 22px
            rgba(15, 23, 42, 0.06);
        }

        .stat-icon {
          position: relative;
          z-index: 1;
          width: 39px;
          height: 39px;
          flex-shrink: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 10px;
          background: #eff6ff;
          font-size: 17px;
        }

        .stat-text {
          position: relative;
          z-index: 1;
        }

        .stat-text span {
          display: block;
          color: #6b7280;
          font-size: 10px;
          font-weight: 600;
          margin-bottom: 3px;
        }

        .stat-text strong {
          display: block;
          color: #111827;
          font-size: 18px;
          font-weight: 800;
        }


        /* =========================================
           TOOLBAR
        ========================================= */

        .products-toolbar {
          background: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 12px;
          padding: 11px 13px;
          margin-bottom: 20px;
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: 15px;
        }

        .search-box {
          position: relative;
          width: 100%;
          max-width: 440px;
        }

        .search-box span {
          position: absolute;
          left: 13px;
          top: 50%;
          transform: translateY(-50%);
          font-size: 13px;
          color: #9ca3af;
          pointer-events: none;
        }

        .search-input {
          width: 100%;
          height: 40px;
          padding: 0 13px 0 37px;
          border: 1px solid #e5e7eb;
          border-radius: 8px;
          outline: none;
          background: #f9fafb;
          color: #374151;
          font-size: 12px;
          box-sizing: border-box;
          transition: all 0.2s ease;
        }

        .search-input::placeholder {
          color: #9ca3af;
        }

        .search-input:focus {
          background: #ffffff;
          border-color: #93c5fd;
          box-shadow:
            0 0 0 3px
            rgba(37, 99, 235, 0.07);
        }

        .showing-count {
          color: #6b7280;
          font-size: 11px;
          white-space: nowrap;
        }

        .showing-count strong {
          color: #2563eb;
        }


        /* =========================================
           GRID
        ========================================= */

        .products-grid {
          display: grid;
          grid-template-columns:
            repeat(4, minmax(0, 1fr));
          gap: 16px;
        }


        /* =========================================
           PRODUCT CARD
        ========================================= */

        .product-card {
          min-width: 0;
          display: flex;
          flex-direction: column;
          background: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 13px;
          overflow: hidden;
          box-shadow:
            0 3px 12px
            rgba(15, 23, 42, 0.035);
          transition:
            transform 0.25s ease,
            box-shadow 0.25s ease,
            border-color 0.25s ease;
        }

        .product-card:hover {
          transform: translateY(-4px);
          border-color: #dbeafe;
          box-shadow:
            0 13px 30px
            rgba(15, 23, 42, 0.09);
        }


        /* =========================================
           IMAGE
        ========================================= */

        .product-image-area {
          position: relative;
          height: 165px;
          overflow: hidden;
          background: #f1f5f9;
        }

        .product-image {
          width: 100%;
          height: 100%;
          display: block;
          object-fit: cover;
          transition:
            transform 0.45s ease;
        }

        .product-card:hover
        .product-image {
          transform: scale(1.05);
        }


        /* =========================================
           PRODUCT ID
        ========================================= */

        .product-number {
          position: absolute;
          top: 10px;
          left: 10px;
          padding: 4px 8px;
          border-radius: 20px;
          background:
            rgba(17, 24, 39, 0.78);
          color: #ffffff;
          font-size: 9px;
          font-weight: 700;
          backdrop-filter: blur(6px);
        }


        /* =========================================
           STOCK PILL
        ========================================= */

        .stock-pill {
          position: absolute;
          top: 10px;
          right: 10px;
          display: inline-flex;
          align-items: center;
          gap: 5px;
          padding: 4px 8px;
          border-radius: 20px;
          font-size: 9px;
          font-weight: 700;
          backdrop-filter: blur(6px);
        }

        .stock-dot {
          width: 5px;
          height: 5px;
          border-radius: 50%;
          background: currentColor;
        }

        .stock-pill.good {
          background: #dcfce7;
          color: #15803d;
        }

        .stock-pill.low {
          background: #fef3c7;
          color: #b45309;
        }

        .stock-pill.out {
          background: #fee2e2;
          color: #b91c1c;
        }


        /* =========================================
           CONTENT
        ========================================= */

        .product-card-content {
          flex: 1;
          display: flex;
          flex-direction: column;
          padding: 15px;
        }

        .product-type {
          color: #2563eb;
          font-size: 8px;
          font-weight: 800;
          letter-spacing: 1.1px;
          margin-bottom: 5px;
        }

        .product-name {
          margin: 0;
          color: #1f2937;
          font-size: 15px;
          line-height: 1.3;
          font-weight: 750;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }

        .product-description {
          min-height: 32px;
          margin: 6px 0 12px;
          color: #6b7280;
          font-size: 11px;
          line-height: 1.5;

          display: -webkit-box;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;
        }


        /* =========================================
           PRICE / STOCK
        ========================================= */

        .product-bottom-info {
          display: flex;
          justify-content: space-between;
          align-items: flex-end;

          padding: 9px 0;
          margin-bottom: 11px;

          border-top: 1px solid #f1f5f9;
          border-bottom: 1px solid #f1f5f9;
        }

        .price-block span,
        .available-block span {
          display: block;
          color: #9ca3af;
          font-size: 8px;
          font-weight: 700;
          letter-spacing: 0.5px;
          margin-bottom: 3px;
        }

        .product-price {
          color: #111827;
          font-size: 17px;
          font-weight: 800;
        }

        .available-block {
          text-align: right;
        }

        .available-block strong {
          color: #374151;
          font-size: 10px;
          font-weight: 700;
        }


        /* =========================================
           CART BUTTON
        ========================================= */

        .cart-button {
          width: 100%;
          min-height: 35px;

          display: flex;
          align-items: center;
          justify-content: center;
          gap: 6px;

          border: none;
          border-radius: 8px;

          background: #2563eb;
          color: #ffffff;

          font-size: 10px;
          font-weight: 700;

          cursor: pointer;
          transition: all 0.2s ease;
        }

        .cart-button:hover:not(:disabled) {
          background: #1d4ed8;
          transform: translateY(-1px);
          box-shadow:
            0 5px 12px
            rgba(37, 99, 235, 0.18);
        }

        .cart-button.added {
          background: #16a34a;
        }

        .cart-button:disabled {
          cursor: not-allowed;
          opacity: 0.8;
        }

        .cart-button:not(.added):disabled {
          background: #9ca3af;
        }


        /* =========================================
           LOADING
        ========================================= */

        .products-loading {
          background: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 13px;
          padding: 60px 20px;
          text-align: center;
        }

        .loading-spinner {
          width: 31px;
          height: 31px;
          margin: 0 auto 12px;
          border: 3px solid #dbeafe;
          border-top-color: #2563eb;
          border-radius: 50%;
          animation:
            productLoading 0.8s linear infinite;
        }

        @keyframes productLoading {
          to {
            transform: rotate(360deg);
          }
        }

        .products-loading p {
          margin: 0;
          color: #6b7280;
          font-size: 12px;
        }


        /* =========================================
           ERROR
        ========================================= */

        .products-error {
          background: #fff7ed;
          border: 1px solid #fed7aa;
          border-radius: 12px;
          padding: 28px 20px;
          text-align: center;
          color: #c2410c;
        }

        .products-error-icon {
          font-size: 25px;
          margin-bottom: 8px;
        }

        .products-error strong {
          display: block;
          margin-bottom: 5px;
          font-size: 14px;
        }

        .products-error p {
          margin: 0;
          font-size: 11px;
        }

        .retry-button {
          margin-top: 12px;
          padding: 8px 14px;
          border: none;
          border-radius: 7px;
          background: #ea580c;
          color: #ffffff;
          font-size: 11px;
          font-weight: 700;
          cursor: pointer;
        }


        /* =========================================
           EMPTY
        ========================================= */

        .products-empty {
          background: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 13px;
          padding: 60px 20px;
          text-align: center;
        }

        .empty-icon {
          width: 58px;
          height: 58px;
          margin: 0 auto 12px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 15px;
          background: #eff6ff;
          font-size: 25px;
        }

        .products-empty h3 {
          margin: 0 0 5px;
          color: #1f2937;
          font-size: 17px;
        }

        .products-empty p {
          margin: 0 0 15px;
          color: #6b7280;
          font-size: 11px;
        }


        /* =========================================
           NO SEARCH RESULT
        ========================================= */

        .no-results {
          grid-column: 1 / -1;
          background: #ffffff;
          border: 1px solid #e5e7eb;
          border-radius: 13px;
          padding: 55px 20px;
          text-align: center;
        }

        .no-results-icon {
          font-size: 30px;
          margin-bottom: 8px;
        }

        .no-results h3 {
          margin: 0 0 5px;
          color: #1f2937;
          font-size: 16px;
        }

        .no-results p {
          margin: 0;
          color: #6b7280;
          font-size: 11px;
        }


        /* =========================================
           RESPONSIVE
        ========================================= */

        @media (max-width: 1200px) {

          .products-grid {
            grid-template-columns:
              repeat(3, minmax(0, 1fr));
          }

        }


        @media (max-width: 950px) {

          .products-stats {
            grid-template-columns:
              repeat(2, 1fr);
          }

          .products-grid {
            grid-template-columns:
              repeat(2, minmax(0, 1fr));
          }

        }


        @media (max-width: 650px) {

          .products-page {
            padding: 20px 15px;
          }

          .products-header {
            align-items: stretch;
            flex-direction: column;
          }

          .products-heading h1 {
            font-size: 24px;
          }

          .products-heading p {
            font-size: 12px;
          }

          .add-product-button {
            width: 100%;
          }

          .products-toolbar {
            align-items: stretch;
            flex-direction: column;
          }

          .search-box {
            max-width: none;
          }

          .showing-count {
            text-align: right;
          }

          .products-grid {
            grid-template-columns: 1fr;
          }

        }


        @media (max-width: 420px) {

          .products-page {
            padding: 15px 10px;
          }

          .products-stats {
            gap: 9px;
          }

          .stat-card {
            padding: 11px;
            gap: 8px;
          }

          .stat-icon {
            width: 34px;
            height: 34px;
            font-size: 14px;
          }

          .stat-text span {
            font-size: 8px;
          }

          .stat-text strong {
            font-size: 15px;
          }

          .product-image-area {
            height: 185px;
          }

        }

      `}</style>


      <div className="products-page">

        {/* =================================
            HEADER
        ================================= */}

        <div className="products-header">

          <div className="products-heading">

            <div className="products-label">
              🛍️ STORE CATALOG
            </div>

            <h1>
              Products
            </h1>

            <p>
              Manage your product catalog,
              pricing and inventory.
            </p>

          </div>

          <button
            className="add-product-button"
            onClick={() =>
              navigate("/add-product")
            }
          >
            + Add Product
          </button>

        </div>


        {/* =================================
            STATS
        ================================= */}

        <div className="products-stats">

          <div className="stat-card">

            <div className="stat-icon">
              📦
            </div>

            <div className="stat-text">

              <span>
                Total Products
              </span>

              <strong>
                {products.length}
              </strong>

            </div>

          </div>


          <div className="stat-card">

            <div className="stat-icon">
              ✓
            </div>

            <div className="stat-text">

              <span>
                In Stock
              </span>

              <strong>
                {inStock}
              </strong>

            </div>

          </div>


          <div className="stat-card">

            <div className="stat-icon">
              ⚠️
            </div>

            <div className="stat-text">

              <span>
                Low Stock
              </span>

              <strong>
                {lowStock}
              </strong>

            </div>

          </div>


          <div className="stat-card">

            <div className="stat-icon">
              🛒
            </div>

            <div className="stat-text">

              <span>
                Cart Items
              </span>

              <strong>
                {cartItems.length}
              </strong>

            </div>

          </div>

        </div>


        {/* =================================
            SEARCH
        ================================= */}

        {!loading && !error && (

          <div className="products-toolbar">

            <div className="search-box">

              <span>
                🔍
              </span>

              <input
                type="text"
                className="search-input"
                placeholder="Search products..."
                value={search}
                onChange={(e) =>
                  setSearch(e.target.value)
                }
              />

            </div>

            <div className="showing-count">

              Showing{" "}

              <strong>
                {filteredProducts.length}
              </strong>

              {" "}of{" "}

              <strong>
                {products.length}
              </strong>

              {" "}products

            </div>

          </div>

        )}


        {/* =================================
            LOADING
        ================================= */}

        {loading && (

          <div className="products-loading">

            <div className="loading-spinner"></div>

            <p>
              Loading products...
            </p>

          </div>

        )}


        {/* =================================
            ERROR
        ================================= */}

        {!loading && error && (

          <div className="products-error">

            <div className="products-error-icon">
              ⚠️
            </div>

            <strong>
              Unable to load products
            </strong>

            <p>
              {error}
            </p>

            <button
              className="retry-button"
              onClick={fetchProducts}
            >
              Try Again
            </button>

          </div>

        )}


        {/* =================================
            EMPTY
        ================================= */}

        {!loading &&
          !error &&
          products.length === 0 && (

            <div className="products-empty">

              <div className="empty-icon">
                📦
              </div>

              <h3>
                No Products Yet
              </h3>

              <p>
                Add your first product to
                start building your catalog.
              </p>

              <button
                className="add-product-button"
                onClick={() =>
                  navigate("/add-product")
                }
              >
                + Add Product
              </button>

            </div>

          )}


        {/* =================================
            PRODUCT GRID
        ================================= */}

        {!loading &&
          !error &&
          products.length > 0 && (

            <div className="products-grid">

              {filteredProducts.length > 0 ? (

                filteredProducts.map((item) => (

                  <ProductCard
                    key={item.id}
                    item={item}
                  />

                ))

              ) : (

                <div className="no-results">

                  <div className="no-results-icon">
                    🔍
                  </div>

                  <h3>
                    No Products Found
                  </h3>

                  <p>
                    Try searching with another
                    product name.
                  </p>

                </div>

              )}

            </div>

          )}

      </div>
    </>
  );
}
